sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   //Type appropriate comment here, and begin script below

    // If no value, nothing to validate
    if (!newValue)
        return;

    // Get parent reference
    var parentSysId = g_form.getValue('twelve_week_cycle');
    if (!parentSysId) 
        return;

    // GlideAjax call to fetch parent dates
    var ga = new GlideAjax('ParentDateValidator');
    ga.addParam('sysparm_name', 'getParentDates');
    ga.addParam('sysparm_parent_sysid', parentSysId);

    ga.getXMLAnswer(function(response) {

        if (!response)
            return;

        // Parse JSON returned from server
        var parentDates = JSON.parse(response);

        // Parse child end date (yyyy-MM-dd)
        var parts = newValue.split("-");
        var childEndDate = new Date(parts[0], parts[1] - 1, parts[2]);

        // Parse parent end date
        var pEnd = parentDates.u_end_date.split("-");
        var parentEndDate = new Date(pEnd[0], pEnd[1] - 1, pEnd[2]);

        // Validation: child end > parent end → invalid
        if (childEndDate < parentEndDate) {
            alert("End Date cannot be after Cycle End Date (" + parentDates.u_end_date + ")");
            g_form.setValue('u_end_date', ''); // clear field
        }
    });
}
